"""Parsers for catalog.txt, movements.txt and orders.txt."""

import datetime
import re
from decimal import Decimal

from .ledger import first_below_zero
from .model import Movement, Order, ParseError, Product, ascii_lower, ascii_upper, unlimited

_SKU = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_PRICE = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
_UINT = re.compile(r"[0-9]+")
_QTY = re.compile(r"[+-]?[0-9]+")
_DATE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_ORDER_ID = re.compile(r"[Ss][Oo]-[0-9]+")
_PIECE = re.compile(r"([^*]*)\*([0-9]+)")
_MOVE = re.compile(
    r"[ \t]*([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL
)
_SPACES = re.compile(r"[ \t]+")
_TAXES = ("standard", "reduced", "zero")


def parse_date(text):
    """``YYYY-MM-DD`` naming a real date, else None."""
    if not _DATE.fullmatch(text):
        return None
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        return None


def _content_lines(text):
    """(line number, line) for every line that is neither blank nor a comment."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw[:-1] if raw.endswith("\r") else raw
        stripped = line.strip(" \t")
        if stripped and not stripped.startswith("#"):
            yield number, line


@unlimited
def parse_catalog(text):
    """Return ``{SKU: Product}`` in file order."""
    catalog = {}
    for number, line in _content_lines(text):
        fields = [f.strip(" \t") for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', found %d" % len(fields))
        sku, name, price, reorder = fields[:4]
        if not _SKU.fullmatch(sku):
            raise ParseError(number, "bad SKU %r (two to four letters, a dash, three digits)" % sku)
        sku = ascii_upper(sku)
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "name is empty")
        if not _PRICE.fullmatch(price):
            raise ParseError(number, "bad price %r (pounds with at most two decimals)" % price)
        value = Decimal(price)
        if value < Decimal("0.01"):
            raise ParseError(number, "price must be at least 0.01")
        if "." not in price:
            price += ".00"
        elif len(price.split(".")[1]) == 1:
            price += "0"
        if not _UINT.fullmatch(reorder):
            raise ParseError(number, "bad reorder level %r (a whole number, zero or more)" % reorder)
        tax = ascii_lower(fields[4]) if len(fields) == 5 else "standard"
        if tax not in _TAXES:
            raise ParseError(number, "bad tax %r (standard, reduced or zero)" % fields[4])
        catalog[sku] = Product(sku, name, Decimal(price), int(reorder), tax)
    return catalog


@unlimited
def parse_movements(text, catalog):
    """Return the movements in file order; stock may never go below zero."""
    movements = []
    for number, line in _content_lines(text):
        match = _MOVE.fullmatch(line)
        if not match:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku, qty_text, note = match.groups()
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, "bad date %r (YYYY-MM-DD, a real date)" % date_text)
        sku = ascii_upper(sku)
        if sku not in catalog:
            raise ParseError(number, "unknown SKU %s" % sku)
        if not _QTY.fullmatch(qty_text):
            raise ParseError(number, "bad quantity %r (a whole number)" % qty_text)
        quantity = int(qty_text)
        if quantity == 0:
            raise ParseError(number, "quantity must not be zero")
        movements.append(Movement(date, sku, quantity, (note or "").strip(" \t"), number))
    bad = first_below_zero(movements)
    if bad is not None:
        raise ParseError(bad.line, "stock of %s would go below zero" % bad.sku)
    return movements


@unlimited
def parse_orders(text, catalog):
    """Return the orders in file order."""
    orders = []
    seen = set()
    for number, line in _content_lines(text):
        tokens = _SPACES.split(line.strip(" \t"))
        if len(tokens) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES, found %d fields" % len(tokens))
        id_text, date_text, customer, lines_text = tokens
        if not _ORDER_ID.fullmatch(id_text):
            raise ParseError(number, "bad order number %r (SO- and digits)" % id_text)
        order_id = ascii_upper(id_text)
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, "bad date %r (YYYY-MM-DD, a real date)" % date_text)
        lines = []
        used = set()
        for piece in lines_text.split(","):
            match = _PIECE.fullmatch(piece)
            if not match:
                raise ParseError(number, "bad order line %r (SKU*QUANTITY)" % piece)
            sku = ascii_upper(match.group(1))
            if sku not in catalog:
                raise ParseError(number, "unknown SKU %s" % sku)
            if sku in used:
                raise ParseError(number, "SKU %s appears twice in the order" % sku)
            quantity = int(match.group(2))
            if quantity < 1:
                raise ParseError(number, "quantity for %s must be at least 1" % sku)
            used.add(sku)
            lines.append((sku, quantity))
        seen.add(order_id)
        orders.append(Order(order_id, date, customer, lines, number))
    return orders
